css:
.krul .vkk-mx{mix-blend-mode:multiply}
.krul .vkw-n img,.krul .vkw-ctr img,.krul .vkw-hd .ph img,.krul .vkw-hero .ph img,.krul .vkp-ctr img{filter:none}
.krul .vkk-dot{display:block;width:100%;height:100%;border-radius:50%;background:#fff;overflow:hidden;box-shadow:0 5px 12px rgba(16,40,60,.13),inset 0 0 0 1px #edf1f4;transition:transform .9s cubic-bezier(.65,0,.25,1)}
.krul .vkk-dot img{display:block;width:100%;height:100%;object-fit:contain}
.krul .vkw-n.on .vkk-dot{box-shadow:0 0 0 3px #0B99BC,0 8px 16px rgba(16,40,60,.18)}
.krul .vkw-n:focus-visible .vkk-dot{box-shadow:0 0 0 3px #12212c}
.krul .vkw-ctr img{width:78%;height:78%}
.krul .vkw-hero .ph img{width:210px;height:210px}
.krul .vkw-hd .ph{overflow:hidden}.krul .vkw-hd .ph img{width:104px;height:104px}
.vkk-ws{display:inline-flex;gap:4px;padding:4px;border-radius:999px;background:#F1F4F6;margin:0 0 14px;max-width:100%}
.vkk-w{border:0;background:transparent;border-radius:999px;padding:10px 16px;font:inherit;font-weight:700;font-size:14px;color:#12212c!important;cursor:pointer;text-decoration:none!important;line-height:1;display:inline-block;white-space:nowrap}
.vkk-w.on{background:#fff;color:#0B7FA0!important;box-shadow:0 2px 8px rgba(16,40,60,.12)}
.vkk-ws-p{margin:2px 0 0}
.vkw-thc .mx .vkk-tc{position:absolute;width:76px;height:76px;border-radius:50%;background:#fff;overflow:hidden;box-shadow:0 8px 14px rgba(0,0,0,.35)}
.vkw-thc .mx .vkk-tc img{position:static;width:100%;height:100%;object-fit:contain;filter:none;transform:scale(1.15)}
.krul a.vkw-pair{text-decoration:none!important}.krul .vkw-pair.on{border-color:#0B99BC;box-shadow:inset 0 0 0 1px #0B99BC}
.vkk-fb{margin:0 0 14px}.vkk-fb .vkw-pairs{border-top:0;padding-top:4px}
.vkp.krul .vkp-th{background:#fff}
.vkp.krul .vkp-lbl{bottom:5%}
@media (max-width:640px){.krul.vkw-m .vkw-hero .ph{width:190px;height:190px}.krul.vkw-m .vkw-hero .ph img{width:170px;height:170px}.vkk-ws{display:flex}.vkk-w{flex:1;text-align:center;padding:11px 8px}}
@media (prefers-reduced-motion:reduce){.krul .vkk-dot{transition:none}}
.vkp.krul{padding-top:16px}.vkp.krul .vkw-ptr{top:-16px}

